-- Synthetic fixture generated by the archived008 application. Never load into a live database.
BEGIN;
CREATE TABLE schema_migrations (name text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP);
-- 001_exchange_core

CREATE TABLE exchange_sessions (
  id uuid PRIMARY KEY,
  state text NOT NULL CHECK (state IN ('ACTIVE', 'CLOSED')),
  created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE UNIQUE INDEX one_active_session ON exchange_sessions (state) WHERE state = 'ACTIVE';

CREATE TABLE exchange_control (
  id integer PRIMARY KEY CHECK (id = 1),
  active_session_id uuid REFERENCES exchange_sessions (id),
  next_sequence bigint NOT NULL DEFAULT 1 CHECK (next_sequence > 0),
  writer_epoch bigint NOT NULL DEFAULT 0 CHECK (writer_epoch >= 0),
  fault text,
  market_state text NOT NULL DEFAULT 'PAUSED' CHECK (market_state IN ('TRADING', 'PAUSED'))
);
INSERT INTO exchange_control (id) VALUES (1);

CREATE TABLE accounts (
  id uuid PRIMARY KEY,
  kind text NOT NULL CHECK (kind IN ('TRADER', 'FEE', 'ISSUANCE')),
  label text NOT NULL CHECK (length(label) BETWEEN 1 AND 80),
  created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE UNIQUE INDEX one_system_account_per_kind ON accounts (kind) WHERE kind IN ('FEE', 'ISSUANCE');

CREATE TABLE balances (
  session_id uuid NOT NULL REFERENCES exchange_sessions (id),
  account_id uuid NOT NULL REFERENCES accounts (id),
  asset text NOT NULL CHECK (asset IN ('BTC-SIM', 'USD-SIM')),
  bucket text NOT NULL CHECK (bucket IN ('AVAILABLE', 'RESERVED')),
  amount numeric(38, 0) NOT NULL CHECK (amount <> 'NaN'::numeric),
  PRIMARY KEY (session_id, account_id, asset, bucket)
);

CREATE TABLE allocations (
  session_id uuid NOT NULL REFERENCES exchange_sessions (id),
  account_id uuid NOT NULL REFERENCES accounts (id),
  command_id uuid NOT NULL,
  PRIMARY KEY (session_id, account_id)
);

CREATE TABLE orders (
  id uuid PRIMARY KEY,
  session_id uuid NOT NULL REFERENCES exchange_sessions (id),
  account_id uuid NOT NULL REFERENCES accounts (id),
  side text NOT NULL CHECK (side IN ('BUY', 'SELL')),
  type text NOT NULL CHECK (type IN ('LIMIT', 'MARKET')),
  status text NOT NULL CHECK (status IN ('OPEN', 'PARTIALLY_FILLED', 'FILLED', 'CANCELED')),
  quantity numeric(38, 0) NOT NULL CHECK (quantity > 0 AND quantity <= 1000000),
  remaining_quantity numeric(38, 0) NOT NULL CHECK (remaining_quantity >= 0 AND remaining_quantity <= quantity AND remaining_quantity <> 'NaN'::numeric),
  price numeric(38, 0) NOT NULL CHECK (price > 0 AND price <= 10000000000),
  acceptance_sequence bigint NOT NULL CHECK (acceptance_sequence > 0),
  reserved_amount numeric(38, 0) NOT NULL CHECK (reserved_amount >= 0 AND reserved_amount <> 'NaN'::numeric),
  cancel_reason text,
  created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE (id, session_id),
  UNIQUE (session_id, acceptance_sequence),
  CHECK (
    (status = 'OPEN' AND remaining_quantity = quantity) OR
    (status = 'PARTIALLY_FILLED' AND remaining_quantity > 0 AND remaining_quantity < quantity) OR
    (status = 'FILLED' AND remaining_quantity = 0) OR
    (status = 'CANCELED' AND remaining_quantity > 0)
  ),
  CHECK (reserved_amount = CASE
    WHEN status IN ('FILLED', 'CANCELED') THEN 0
    WHEN side = 'BUY' THEN remaining_quantity * price * 1001
    ELSE remaining_quantity
  END)
);
CREATE INDEX sell_book ON orders (session_id, price ASC, acceptance_sequence ASC)
  WHERE side = 'SELL' AND status IN ('OPEN', 'PARTIALLY_FILLED');
CREATE INDEX buy_book ON orders (session_id, price DESC, acceptance_sequence ASC)
  WHERE side = 'BUY' AND status IN ('OPEN', 'PARTIALLY_FILLED');
CREATE INDEX account_orders ON orders (session_id, account_id, acceptance_sequence);

CREATE TABLE fills (
  id uuid PRIMARY KEY,
  session_id uuid NOT NULL REFERENCES exchange_sessions (id),
  maker_order_id uuid NOT NULL,
  taker_order_id uuid NOT NULL,
  buy_order_id uuid NOT NULL,
  sell_order_id uuid NOT NULL,
  quantity numeric(38, 0) NOT NULL CHECK (quantity > 0 AND quantity <> 'NaN'::numeric),
  price numeric(38, 0) NOT NULL CHECK (price > 0 AND price <> 'NaN'::numeric),
  notional numeric(38, 0) NOT NULL CHECK (notional = quantity * price * 1000),
  buyer_fee numeric(38, 0) NOT NULL CHECK (buyer_fee = quantity * price),
  seller_fee numeric(38, 0) NOT NULL CHECK (seller_fee = quantity * price),
  sequence bigint NOT NULL CHECK (sequence > 0),
  fill_index integer NOT NULL CHECK (fill_index >= 0),
  created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE (session_id, sequence, fill_index),
  CHECK (maker_order_id <> taker_order_id AND buy_order_id <> sell_order_id),
  CHECK (
    (maker_order_id = buy_order_id AND taker_order_id = sell_order_id) OR
    (maker_order_id = sell_order_id AND taker_order_id = buy_order_id)
  ),
  FOREIGN KEY (maker_order_id, session_id) REFERENCES orders (id, session_id),
  FOREIGN KEY (taker_order_id, session_id) REFERENCES orders (id, session_id),
  FOREIGN KEY (buy_order_id, session_id) REFERENCES orders (id, session_id),
  FOREIGN KEY (sell_order_id, session_id) REFERENCES orders (id, session_id)
);
CREATE INDEX session_fills ON fills (session_id, sequence);

CREATE TABLE journal_transactions (
  id uuid PRIMARY KEY,
  session_id uuid NOT NULL REFERENCES exchange_sessions (id),
  command_id uuid NOT NULL,
  kind text NOT NULL CHECK (length(kind) BETWEEN 1 AND 80),
  created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  created_xid xid8 NOT NULL DEFAULT pg_current_xact_id(),
  UNIQUE (id, session_id)
);

CREATE TABLE journal_entries (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  journal_transaction_id uuid NOT NULL,
  session_id uuid NOT NULL,
  account_id uuid NOT NULL REFERENCES accounts (id),
  asset text NOT NULL CHECK (asset IN ('BTC-SIM', 'USD-SIM')),
  bucket text NOT NULL CHECK (bucket IN ('AVAILABLE', 'RESERVED')),
  amount numeric(38, 0) NOT NULL CHECK (amount <> 0 AND amount <> 'NaN'::numeric),
  FOREIGN KEY (journal_transaction_id, session_id) REFERENCES journal_transactions (id, session_id)
);
CREATE INDEX journal_by_transaction ON journal_entries (journal_transaction_id, asset);
CREATE INDEX journal_by_balance ON journal_entries (session_id, account_id, asset, bucket);

CREATE TABLE receipts (
  actor_id uuid NOT NULL REFERENCES accounts (id),
  command_id uuid NOT NULL,
  session_id uuid NOT NULL,
  payload_hash text NOT NULL CHECK (length(payload_hash) = 64),
  result jsonb NOT NULL CHECK (jsonb_typeof(result) = 'object'),
  sequence bigint NOT NULL CHECK (sequence > 0),
  created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (actor_id, command_id)
);

CREATE TABLE outbox (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  session_id uuid NOT NULL,
  sequence bigint NOT NULL CHECK (sequence > 0),
  event_type text NOT NULL CHECK (length(event_type) BETWEEN 1 AND 80),
  payload jsonb NOT NULL CHECK (jsonb_typeof(payload) = 'object'),
  created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX outbox_session_cursor ON outbox (session_id, id);

CREATE FUNCTION reject_immutable_change() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION '% is append-only', TG_TABLE_NAME USING ERRCODE = '23514';
END;
$$;

CREATE TRIGGER immutable_journal_transactions BEFORE UPDATE OR DELETE ON journal_transactions
  FOR EACH ROW EXECUTE FUNCTION reject_immutable_change();
CREATE TRIGGER immutable_journal_entries BEFORE UPDATE OR DELETE ON journal_entries
  FOR EACH ROW EXECUTE FUNCTION reject_immutable_change();
CREATE TRIGGER immutable_fills BEFORE UPDATE OR DELETE ON fills
  FOR EACH ROW EXECUTE FUNCTION reject_immutable_change();
CREATE TRIGGER immutable_receipts BEFORE UPDATE OR DELETE ON receipts
  FOR EACH ROW EXECUTE FUNCTION reject_immutable_change();
CREATE TRIGGER immutable_outbox BEFORE UPDATE OR DELETE ON outbox
  FOR EACH ROW EXECUTE FUNCTION reject_immutable_change();
CREATE TRIGGER immutable_allocations BEFORE UPDATE OR DELETE ON allocations
  FOR EACH ROW EXECUTE FUNCTION reject_immutable_change();

CREATE FUNCTION validate_new_journal_entry() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
  header_xid xid8;
BEGIN
  SELECT created_xid INTO header_xid FROM journal_transactions
    WHERE id = NEW.journal_transaction_id;
  IF header_xid IS DISTINCT FROM pg_current_xact_id() THEN
    RAISE EXCEPTION 'Cannot append to an already committed journal transaction' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;
CREATE TRIGGER journal_entry_transaction_boundary BEFORE INSERT ON journal_entries
  FOR EACH ROW EXECUTE FUNCTION validate_new_journal_entry();

CREATE FUNCTION validate_journal_balance() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM journal_entries WHERE journal_transaction_id = NEW.id) THEN
    RAISE EXCEPTION 'Journal transaction must contain entries' USING ERRCODE = '23514';
  END IF;
  IF EXISTS (
    SELECT asset FROM journal_entries WHERE journal_transaction_id = NEW.id
    GROUP BY asset HAVING sum(amount) <> 0
  ) THEN
    RAISE EXCEPTION 'Journal transaction must balance separately for every asset' USING ERRCODE = '23514';
  END IF;
  RETURN NULL;
END;
$$;
CREATE CONSTRAINT TRIGGER balanced_journal AFTER INSERT ON journal_transactions
  DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION validate_journal_balance();

CREATE FUNCTION validate_balance_sign() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM balances b JOIN accounts a ON a.id = b.account_id
    WHERE b.session_id = NEW.session_id AND b.account_id = NEW.account_id
      AND b.asset = NEW.asset AND b.bucket = NEW.bucket AND b.amount < 0
      AND (b.bucket = 'RESERVED' OR a.kind <> 'ISSUANCE')
  ) THEN
    RAISE EXCEPTION 'Spendable and reserved balances cannot be negative' USING ERRCODE = '23514';
  END IF;
  RETURN NULL;
END;
$$;
CREATE CONSTRAINT TRIGGER nonnegative_balances AFTER INSERT OR UPDATE ON balances
  DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION validate_balance_sign();

-- 002_identity_and_controls

ALTER TABLE accounts DROP CONSTRAINT accounts_kind_check;
ALTER TABLE accounts ADD CONSTRAINT accounts_kind_check CHECK (kind IN ('TRADER', 'ADMIN', 'FEE', 'ISSUANCE'));
ALTER TABLE accounts ADD CONSTRAINT account_role_identity UNIQUE (id, kind);
CREATE UNIQUE INDEX one_administrator_account ON accounts (kind) WHERE kind = 'ADMIN';

CREATE TABLE users (
  account_id uuid PRIMARY KEY,
  role text NOT NULL CHECK (role IN ('ADMIN', 'TRADER')),
  handle text NOT NULL UNIQUE CHECK (handle ~ '^[a-z][a-z0-9_]{2,31}$'),
  password_hash text NOT NULL CHECK (length(password_hash) BETWEEN 1 AND 512),
  status text NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE', 'SUSPENDED')),
  suspension_reason text,
  pending_cancellation boolean NOT NULL DEFAULT false,
  created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (account_id, role) REFERENCES accounts (id, kind),
  CHECK (role <> 'ADMIN' OR (status = 'ACTIVE' AND NOT pending_cancellation)),
  CHECK (NOT pending_cancellation OR status = 'SUSPENDED')
);
CREATE UNIQUE INDEX one_administrator_identity ON users (role) WHERE role = 'ADMIN';

CREATE TABLE login_sessions (
  token_hash text PRIMARY KEY CHECK (token_hash ~ '^[0-9a-f]{64}$'),
  account_id uuid NOT NULL REFERENCES users (account_id),
  csrf_hash text NOT NULL CHECK (csrf_hash ~ '^[0-9a-f]{64}$'),
  expires_at timestamptz NOT NULL,
  revoked_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CHECK (expires_at > created_at)
);
CREATE INDEX login_sessions_account ON login_sessions (account_id);

CREATE TABLE invitations (
  id uuid PRIMARY KEY,
  token_hash text NOT NULL UNIQUE CHECK (token_hash ~ '^[0-9a-f]{64}$'),
  created_by uuid NOT NULL REFERENCES users (account_id),
  expires_at timestamptz NOT NULL,
  revoked_at timestamptz,
  redeemed_at timestamptz,
  redeemed_by uuid REFERENCES users (account_id),
  created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CHECK (expires_at > created_at),
  CHECK ((redeemed_at IS NULL) = (redeemed_by IS NULL))
);

CREATE TABLE recovery_tokens (
  id uuid PRIMARY KEY,
  token_hash text NOT NULL UNIQUE CHECK (token_hash ~ '^[0-9a-f]{64}$'),
  account_id uuid NOT NULL REFERENCES users (account_id),
  created_by uuid NOT NULL REFERENCES users (account_id),
  expires_at timestamptz NOT NULL,
  used_at timestamptz,
  revoked_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CHECK (expires_at > created_at)
);
CREATE INDEX recovery_tokens_account ON recovery_tokens (account_id);

CREATE TABLE admin_audit (
  id uuid PRIMARY KEY,
  actor_id uuid NOT NULL REFERENCES accounts (id),
  command_id uuid NOT NULL,
  session_id uuid REFERENCES exchange_sessions (id),
  action text NOT NULL CHECK (length(action) BETWEEN 1 AND 80),
  target_id uuid,
  reason text NOT NULL CHECK (length(reason) BETWEEN 1 AND 500),
  result jsonb NOT NULL CHECK (jsonb_typeof(result) = 'object'),
  created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX admin_audit_session ON admin_audit (session_id, created_at, id);
CREATE TRIGGER immutable_admin_audit BEFORE UPDATE OR DELETE ON admin_audit
  FOR EACH ROW EXECUTE FUNCTION reject_immutable_change();

CREATE TABLE grants (
  id uuid PRIMARY KEY,
  session_id uuid NOT NULL REFERENCES exchange_sessions (id),
  account_id uuid NOT NULL REFERENCES users (account_id),
  actor_id uuid NOT NULL REFERENCES users (account_id),
  command_id uuid NOT NULL,
  asset text NOT NULL CHECK (asset IN ('BTC-SIM', 'USD-SIM')),
  amount numeric(38, 0) NOT NULL CHECK (amount > 0 AND amount <> 'NaN'::numeric
    AND amount <= CASE WHEN asset = 'BTC-SIM' THEN 1000000 ELSE 10000000000000000 END),
  reason text NOT NULL CHECK (length(reason) BETWEEN 1 AND 500),
  created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE (actor_id, command_id)
);
CREATE INDEX grants_account ON grants (session_id, account_id);
CREATE TRIGGER immutable_grants BEFORE UPDATE OR DELETE ON grants
  FOR EACH ROW EXECUTE FUNCTION reject_immutable_change();

CREATE FUNCTION reject_administrator_funding() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF EXISTS (SELECT 1 FROM accounts WHERE id = NEW.account_id AND kind = 'ADMIN') THEN
    RAISE EXCEPTION 'Administrator identities cannot hold funds or trade' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;
CREATE TRIGGER no_admin_balances BEFORE INSERT OR UPDATE ON balances
  FOR EACH ROW EXECUTE FUNCTION reject_administrator_funding();
CREATE TRIGGER no_admin_orders BEFORE INSERT OR UPDATE ON orders
  FOR EACH ROW EXECUTE FUNCTION reject_administrator_funding();
CREATE TRIGGER no_admin_allocations BEFORE INSERT ON allocations
  FOR EACH ROW EXECUTE FUNCTION reject_administrator_funding();
CREATE TRIGGER no_admin_grants BEFORE INSERT ON grants
  FOR EACH ROW EXECUTE FUNCTION reject_administrator_funding();
CREATE TRIGGER no_admin_journal BEFORE INSERT ON journal_entries
  FOR EACH ROW EXECUTE FUNCTION reject_administrator_funding();

-- 003_demo_market

CREATE TABLE demo_market (
  session_id uuid PRIMARY KEY REFERENCES exchange_sessions (id),
  maker_account_id uuid NOT NULL REFERENCES accounts (id),
  taker_account_id uuid NOT NULL REFERENCES accounts (id),
  enabled boolean NOT NULL DEFAULT false,
  status text NOT NULL CHECK (status IN ('RUNNING', 'STOPPED', 'LIMITED_INVENTORY', 'ERROR')),
  cycle bigint NOT NULL DEFAULT 0 CHECK (cycle >= 0),
  reference_price bigint NOT NULL DEFAULT 5000000 CHECK (reference_price BETWEEN 4800000 AND 5200000),
  plan jsonb NOT NULL DEFAULT '[]' CHECK (jsonb_typeof(plan) = 'array'),
  next_command integer NOT NULL DEFAULT 0 CHECK (next_command >= 0 AND next_command <= jsonb_array_length(plan)),
  updated_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CHECK (maker_account_id <> taker_account_id)
);

-- 004_simulator_controls

ALTER TABLE demo_market ADD COLUMN generation bigint NOT NULL DEFAULT 0 CHECK (generation >= 0);
ALTER TABLE demo_market DROP CONSTRAINT demo_market_status_check;
ALTER TABLE demo_market ADD CONSTRAINT demo_market_status_check
  CHECK (status IN ('RUNNING', 'STOPPED', 'STOPPING', 'LIMITED_INVENTORY', 'ERROR'));

ALTER TABLE grants DROP CONSTRAINT grants_account_id_fkey;
ALTER TABLE grants ADD CONSTRAINT grants_account_id_fkey
  FOREIGN KEY (account_id) REFERENCES accounts (id);

CREATE FUNCTION validate_grant_recipient() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM accounts WHERE id = NEW.account_id AND kind = 'TRADER')
     OR NOT (
       EXISTS (SELECT 1 FROM users WHERE account_id = NEW.account_id AND role = 'TRADER')
       OR EXISTS (SELECT 1 FROM demo_market WHERE session_id = NEW.session_id
         AND NEW.account_id IN (maker_account_id, taker_account_id))
     ) THEN
    RAISE EXCEPTION 'Grant recipient must be an enrolled trader or registered simulator account'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;
CREATE TRIGGER valid_grant_recipient BEFORE INSERT ON grants
  FOR EACH ROW EXECUTE FUNCTION validate_grant_recipient();

-- 005_market_orders

CREATE TABLE market_previews (
  id uuid PRIMARY KEY,
  account_id uuid NOT NULL REFERENCES accounts (id),
  session_id uuid NOT NULL REFERENCES exchange_sessions (id),
  side text NOT NULL CHECK (side IN ('BUY', 'SELL')),
  quantity numeric(38, 0) NOT NULL CHECK (quantity > 0 AND quantity <= 1000000),
  reference_price numeric(38, 0) NOT NULL CHECK (reference_price > 0 AND reference_price <= 10000000000),
  guard_price numeric(38, 0) NOT NULL CHECK (guard_price > 0 AND guard_price <= 10000000000),
  created_at timestamptz NOT NULL,
  expires_at timestamptz NOT NULL,
  UNIQUE (id, account_id, session_id),
  CHECK (expires_at = created_at + interval '10 seconds'),
  CHECK (quantity * guard_price * 1000 >= 1000000000),
  CHECK (guard_price = CASE WHEN side = 'BUY'
    THEN floor(reference_price * 105 / 100)
    ELSE ceil(reference_price * 95 / 100) END)
);
CREATE TRIGGER immutable_market_previews BEFORE UPDATE OR DELETE ON market_previews
  FOR EACH ROW EXECUTE FUNCTION reject_immutable_change();

CREATE TABLE market_preview_uses (
  preview_id uuid PRIMARY KEY,
  actor_id uuid NOT NULL,
  session_id uuid NOT NULL,
  command_id uuid NOT NULL,
  created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE (actor_id, command_id),
  FOREIGN KEY (preview_id, actor_id, session_id)
    REFERENCES market_previews (id, account_id, session_id),
  FOREIGN KEY (actor_id, command_id) REFERENCES receipts (actor_id, command_id)
    DEFERRABLE INITIALLY DEFERRED
);
CREATE TRIGGER immutable_market_preview_uses BEFORE UPDATE OR DELETE ON market_preview_uses
  FOR EACH ROW EXECUTE FUNCTION reject_immutable_change();

ALTER TABLE orders ADD CONSTRAINT market_orders_never_rest
  CHECK (type <> 'MARKET' OR (status IN ('FILLED', 'CANCELED') AND reserved_amount = 0));

-- 006_session_lifecycle

ALTER TABLE exchange_sessions ADD COLUMN closed_at timestamptz;
UPDATE exchange_sessions SET closed_at = created_at WHERE state = 'CLOSED';
ALTER TABLE exchange_sessions ADD CONSTRAINT session_close_timestamp
  CHECK ((state = 'ACTIVE' AND closed_at IS NULL) OR (state = 'CLOSED' AND closed_at IS NOT NULL));

CREATE TABLE session_rollovers (
  id uuid PRIMARY KEY,
  actor_id uuid NOT NULL REFERENCES accounts (id),
  command_id uuid NOT NULL,
  previous_session_id uuid NOT NULL REFERENCES exchange_sessions (id),
  new_session_id uuid NOT NULL UNIQUE,
  payload_hash text NOT NULL,
  reason text NOT NULL CHECK (length(reason) BETWEEN 1 AND 500),
  state text NOT NULL CHECK (state IN ('IN_PROGRESS', 'COMPLETED')),
  started_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  completed_at timestamptz,
  UNIQUE (actor_id, command_id),
  UNIQUE (previous_session_id),
  CHECK (previous_session_id <> new_session_id),
  CHECK ((state = 'IN_PROGRESS' AND completed_at IS NULL) OR
    (state = 'COMPLETED' AND completed_at IS NOT NULL))
);
ALTER TABLE exchange_control ADD COLUMN rollover_operation_id uuid REFERENCES session_rollovers (id);
ALTER TABLE exchange_control ADD CONSTRAINT rollover_is_paused
  CHECK (rollover_operation_id IS NULL OR market_state = 'PAUSED');

CREATE FUNCTION protect_session_rollover() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'DELETE' OR OLD.state = 'COMPLETED' OR
    (NEW.id, NEW.actor_id, NEW.command_id, NEW.previous_session_id, NEW.new_session_id,
      NEW.payload_hash, NEW.reason, NEW.started_at) IS DISTINCT FROM
    (OLD.id, OLD.actor_id, OLD.command_id, OLD.previous_session_id, OLD.new_session_id,
      OLD.payload_hash, OLD.reason, OLD.started_at) THEN
    RAISE EXCEPTION 'Session rollover identity and completed outcome are immutable' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;
CREATE TRIGGER immutable_rollover BEFORE UPDATE OR DELETE ON session_rollovers
  FOR EACH ROW EXECUTE FUNCTION protect_session_rollover();

CREATE FUNCTION protect_closed_session() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF OLD.state = 'CLOSED' THEN
    RAISE EXCEPTION 'Archived sessions cannot be changed or deleted' USING ERRCODE = '23514';
  END IF;
  IF TG_OP = 'UPDATE' AND (NEW.id, NEW.created_at) IS DISTINCT FROM (OLD.id, OLD.created_at) THEN
    RAISE EXCEPTION 'Session identity is immutable' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;
CREATE TRIGGER immutable_closed_session BEFORE UPDATE OR DELETE ON exchange_sessions
  FOR EACH ROW EXECUTE FUNCTION protect_closed_session();

CREATE FUNCTION require_active_financial_session() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE target_session uuid;
BEGIN
  target_session := CASE WHEN TG_OP = 'DELETE' THEN OLD.session_id ELSE NEW.session_id END;
  IF NOT EXISTS (SELECT 1 FROM exchange_sessions WHERE id = target_session AND state = 'ACTIVE') OR
    (TG_OP = 'UPDATE' AND EXISTS (
      SELECT 1 FROM exchange_sessions WHERE id = OLD.session_id AND state = 'CLOSED'
    )) THEN
    RAISE EXCEPTION 'Archived financial history is read only' USING ERRCODE = '23514';
  END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$$;
CREATE TRIGGER active_balance_session BEFORE INSERT OR UPDATE OR DELETE ON balances
  FOR EACH ROW EXECUTE FUNCTION require_active_financial_session();
CREATE TRIGGER active_order_session BEFORE INSERT OR UPDATE OR DELETE ON orders
  FOR EACH ROW EXECUTE FUNCTION require_active_financial_session();
CREATE TRIGGER active_fill_session BEFORE INSERT OR UPDATE OR DELETE ON fills
  FOR EACH ROW EXECUTE FUNCTION require_active_financial_session();
CREATE TRIGGER active_allocation_session BEFORE INSERT OR UPDATE OR DELETE ON allocations
  FOR EACH ROW EXECUTE FUNCTION require_active_financial_session();
CREATE TRIGGER active_grant_session BEFORE INSERT OR UPDATE OR DELETE ON grants
  FOR EACH ROW EXECUTE FUNCTION require_active_financial_session();
CREATE TRIGGER active_journal_session BEFORE INSERT OR UPDATE OR DELETE ON journal_transactions
  FOR EACH ROW EXECUTE FUNCTION require_active_financial_session();
CREATE TRIGGER active_entry_session BEFORE INSERT OR UPDATE OR DELETE ON journal_entries
  FOR EACH ROW EXECUTE FUNCTION require_active_financial_session();
CREATE TRIGGER active_simulator_session BEFORE INSERT OR UPDATE OR DELETE ON demo_market
  FOR EACH ROW EXECUTE FUNCTION require_active_financial_session();

-- 007_command_timestamps

CREATE FUNCTION exchange_command_timestamp() RETURNS timestamptz
LANGUAGE sql VOLATILE AS $$
  SELECT COALESCE(
    NULLIF(current_setting('sandbox.command_timestamp', true), '')::timestamptz,
    clock_timestamp()
  );
$$;

ALTER TABLE exchange_sessions ALTER COLUMN created_at SET DEFAULT exchange_command_timestamp();
ALTER TABLE accounts ALTER COLUMN created_at SET DEFAULT exchange_command_timestamp();
ALTER TABLE orders ALTER COLUMN created_at SET DEFAULT exchange_command_timestamp();
ALTER TABLE orders ALTER COLUMN updated_at SET DEFAULT exchange_command_timestamp();
ALTER TABLE fills ALTER COLUMN created_at SET DEFAULT exchange_command_timestamp();
ALTER TABLE journal_transactions ALTER COLUMN created_at SET DEFAULT exchange_command_timestamp();
ALTER TABLE receipts ALTER COLUMN created_at SET DEFAULT exchange_command_timestamp();
